def ui(key, title, description, detail, category="Интерфейс", caution="", recommended=False):
    return Tweak(key, title, description, detail, category,
                 "mouse" if category == "Управление" else "spark", SPI_SOURCE,
                 recommended, caution, category,
                 "Действует сразу; конкретное приложение может использовать собственные эффекты или ввод.")


